[
  {
    "statement": "Double fyke nets appear to be an effective method for controlling American bullfrogs in small ponds.",
    "citations": [
      "1046",
      "1045"
    ]
  },
  {
    "statement": "Double fyke nets are particularly effective for targeting juvenile and tadpole American bullfrogs.",
    "citations": [
      "1046"
    ]
  },
  {
    "statement": "Double fyke nets were effective in catching bullfrog tadpoles in small shallow ponds in Belgium.",
    "citations": [
      "1046"
    ]
  },
  {
    "statement": "The catchability of adult bullfrogs in small shallow ponds using one double fyke net for 24 hours was very low in Belgium.",
    "citations": [
      "1045"
    ]
  },
  {
    "statement": "Adult bullfrogs can be captured overnight in a single trap floating on the water surface in the USA.",
    "citations": [
      "1045"
    ]
  },
  {
    "statement": "Bullfrog populations rapidly rebounded following intensive removal of adult bullfrogs.",
    "citations": [
      "1045"
    ]
  },
  {
    "statement": "The removal of only adult bullfrogs may not be a sustainable control method.",
    "citations": [
      "1045"
    ]
  },
  {
    "statement": "Combination treatments for bullfrog control appear to be more effective than single methods.",
    "citations": [
      "1045",
      "1046"
    ]
  },
  {
    "statement": "Significant reductions in bullfrog numbers were observed in France when shooting of metamorphosed individuals and juvenile removal by trapping were carried out together.",
    "citations": [
      "1045",
      "1046"
    ]
  },
  {
    "statement": "Chemical control of American bullfrogs is possible using several biocides.",
    "citations": [
      "1048"
    ]
  },
  {
    "statement": "A 10% solution of caffeine has been identified as a biocide that kills American bullfrogs.",
    "citations": [
      "1048"
    ]
  },
  {
    "statement": "A 5% solution of chloroxylenol has been identified as a biocide that kills American bullfrogs.",
    "citations": [
      "1048"
    ]
  },
  {
    "statement": "A combined solution of 4.6% Permethrin and 1% Rotenone has been identified as a biocide that kills American bullfrogs.",
    "citations": [
      "1048"
    ]
  },
  {
    "statement": "No direct evidence was found to support pond draining or pond destruction as methods for controlling American bullfrogs.",
    "citations": [
      "1042",
      "1043"
    ]
  }
]

[
  {
    "statement": "There is no evidence available to determine which method is more effective for controlling Procambarus crayfish.",
    "citations": []
  },
