    "citations": [
      "1034"
    ]
  },
  {
    "statement": "No studies were found that directly and quantitatively tested control methods of removing food sources or draining waterways during systematic journal and report searches.",
    "citations": [
      "1033",
      "1034"
    ]
  },
  {
    "statement": "The effectiveness of removing food sources as a control method for Procambarus crayfish has not been assessed.",
    "citations": [
      "1033"
    ]
  },
  {
    "statement": "The effectiveness of draining waterways as a control method for Procambarus crayfish has not been assessed.",
    "citations": [
      "1034"
    ]
  }
]

[
  {
    "statement": "There is no available evidence regarding the effectiveness of using chemical biocides to specifically control invasive zebra mussel populations.",
    "citations": []
  },
  {
    "statement": "No studies were found that evaluated the effects of using biocides or other chemicals to control non-native, invasive, or other problematic species on subtidal benthic invertebrate populations.",
    "citations": [
      "2171"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects of using biocides or other chemicals to control invasive or problematic species on marine and freshwater mammal populations.",
    "citations": [
      "2937"
    ]
  },
  {
    "statement": "There is some evidence of chemical control effectiveness for other aquatic invasive species.",
    "citations": [
      "1036",
      "1095"
    ]
  },
  {
    "statement": "Red swamp crayfish could be killed using natural pyrethrum Pyblast at a concentration of 0.05 mg/l.",
    "citations": [
      "1036"
    ]
  },
  {
    "statement": "Iodine solution, acetic acid, Virkon S, and sodium hypochlorite killed invasive killer shrimp in laboratory conditions.",
    "citations": [
      "1095"
    ]
  },
  {
    "statement": "The use of iodine solution, acetic acid, Virkon S, and sodium hypochlorite to control invasive killer shrimp were considered impractical for field application.",
    "citations": [
      "1095"
    ]
  },
  {
    "statement": "No specific studies were found that directly evaluated chemical biocide effectiveness against zebra mussels.",
    "citations": []
  }
