[
  {
    "statement": "No specific evidence was found regarding the long-term impacts on native invertebrate communities after eradicating black bullheads using rotenone.",
    "citations": []
  },
  {
    "statement": "The action documents reviewed focus on the effectiveness of rotenone as a biocide for black bullhead eradication.",
    "citations": [
      "1050"
    ]
  },
  {
    "statement": "The action documents reviewed focus on the effects of rotenone on amphibian populations.",
    "citations": [
      "828"
    ]
  },
  {
    "statement": "The reviewed action documents do not contain information about impacts on invertebrate communities.",
    "citations": []
  },
  {
    "statement": "Rotenone successfully achieved eradication of black bullhead in studies from the UK and USA.",
    "citations": [
      "1050"
    ]
  },
  {
    "statement": "Rotenone's effects on amphibians have been found to be both positive and negative.",
    "citations": [
      "828"
    ]
  },
  {
    "statement": "Positive effects of rotenone on amphibians include increased amphibian species numbers and abundance.",
    "citations": [
      "828"
    ]
  },
  {
    "statement": "Negative effects of rotenone on amphibians include mortality in frogs and adverse symptoms in newts.",
    "citations": [
      "828"
    ]
  },
  {
    "statement": "No data is provided on invertebrate community responses to rotenone.",
    "citations": [
      "828"
    ]
  },
  {
    "statement": "No data is provided on long-term ecological recovery patterns after rotenone use.",
    "citations": [
      "828"
    ]
  }
]

[
  {
    "statement": "There is limited information comparing the cost-effectiveness of introducing northern pike versus direct removal of adults for controlling American bullfrog populations.",
    "citations": []
  },
  {
    "statement": "One replicated, controlled study conducted in Belgium found the introduction of the northern pike led to a strong decline in bullfrog tadpole numbers.",
    "citations": [
      "1039"
    ]
  },
  {
    "statement": "For direct removal of adult bullfrogs, the evidence shows mixed results.",
    "citations": []
  },
  {
    "statement": "One replicated study in Belgium found the catchability of adult bullfrogs in small shallow ponds using one double fyke net for 24 hours to be very low.",
    "citations": [
      "1045"
    ]
  },
  {
    "statement": "One small study in the USA found that bullfrog adults can be captured overnight in a single trap floating on the water surface.",
    "citations": [
      "1045"
    ]
  },
  {
    "statement": "One replicated, controlled study in the USA found that bullfrog populations rapidly rebounded following intensive removal of the adults.",
    "citations": [
      "1045"
    ]
  },
  {
    "statement": "A before-and-after study in France found a significant reduction in the number of recorded adults and juveniles following the shooting of metamorphosed individuals before reproduction.",
    "citations": [
      "1045"
    ]
  },
  {
    "statement": "The shooting of metamorphosed individuals was carried out as part of a combination treatment.",
    "citations": [
      "1045"
    ]
  },
  {
    "statement": "The source documents do not provide specific cost-effectiveness comparisons between the methods of introducing northern pike and the direct removal of adult bullfrogs.",
    "citations": []
  }
]

[
  {
    "statement": "No evidence was captured for use of electrofishing to reduce the population size of invasive Ponto-Caspian gobies.",
